      "fact": "This is the tallest bar in the chart, extending to the top grid line of the y-axis scale."
    },
    {
      "location": "First bar from left (Apr)",
      "fact": "This bar is the second tallest, reaching nearly the 30,000 level on the y-axis."
    },
    {
      "location": "Fifth bar from left (Mar)",
      "fact": "This bar is the third tallest, reaching slightly above the 25,000 level."
    },
    {
      "location": "Fourth bar from left (Feb)",
      "fact": "This bar reaches exactly the 20,000 grid line."
    },
    {
      "location": "Third bar from left (Jun)",
      "fact": "This bar is the second shortest, reaching between the 15,000 and 20,000 grid lines."
    },
    {
      "location": "Comparison of May to all other bars",
      "fact": "The May bar is visually distinct from all other bars by an order of magnitude in height; it is the only bar that does not clearly extend into the main plotting area above the 10,000 mark."
    }
