  "printed_facts": [
    {
      "location": "Top left",
      "fact": "Title text: 'Monthly Solar Generation Output'"
    },
    {
      "location": "Left vertical axis",
      "fact": "Axis label: 'Solar output (MWh)'. Tick marks are labeled 10,000, 15,000, 20,000, 25,000, 30,000, 35,000, 40,000."
    },
